    # lookup can interfere. The deterministic ordering is the key:
    # change_password (auth_service.py) first calls
    # retrieve_password_reset_data_by_user_id, which returns the
    # seeded UserPasswordReset document for the query user id, and
    # only then calls verify_password_reset_token with THAT
    # record's secret. The token here is minted with exactly that
    # secret (mirroring encode_activation_token: user_id, email,
    # type, exp, iat, signed with the record's token_secret under
    # ALGORITHM), with the query user id as its payload user id,
    # so decoding SUCCEEDS and the payload-user-id check in
    # change_password is never reached -- but the type check inside
    # verify_password_reset_token (jwt_token_service.py) raises
    # InvalidOperationException ("Invalid token type") first. That
    # raise is NOT caught by the function's own except clauses
    # (ExpiredSignatureError, InvalidTokenError, ValidationError),
    # since InvalidOperationException is an ApiBaseException, not
    # a jwt error, so it propagates BEFORE any password update,
    # record deletion, or notification email -- so no live mail
    # server is needed, unlike the success branch, and the seeded
    # record is never consumed. The exact message pins this
    # branch: it is distinct from the no-record branch ("Invalid or
    # expired password reset token."), the invalid-token branch
    # ("Invalid password reset token" with NO period), and the
    # wrong-user-token branch ("Invalid password reset token."
    # WITH a period), all different raises around the same call.
    # No X-Tenant-ID header is sent, so the seed and the service
    # read use the host test DB, and the conftest fixture drops
    # the test DB after the test, so the row cannot leak into
    # other tests. The central ApiBaseException handler maps
    # InvalidOperationException to 406 with body {"error": ...,
    # "code": 406} and Cache-Control: no-store plus Pragma: no-cache
    # (api/__init__.py), and the pure-ASGI security-headers
    # middleware stamps every HTTP response with no path exclusions.
    import jwt
    from datetime import datetime, timedelta, timezone

    from beanie import PydanticObjectId

    from api.common.security import ALGORITHM
    from api.domain.entities.user_password_reset import UserPasswordReset

    record_secret = "wrong-type-token-test-secret"
    await UserPasswordReset(
        user_id=PydanticObjectId("68c302ef6bf7a039b7e9b385"),
        token_secret=record_secret,
        reset_secret_updated_at=datetime.now(timezone.utc),
        first_name="Test",
    ).insert()
    token = jwt.encode(
        {
            "user_id": "68c302ef6bf7a039b7e9b385",
            "email": "test@example.com",
            "type": "activation",
            "exp": datetime.now(timezone.utc) + timedelta(hours=1),
            "iat": datetime.now(timezone.utc),
        },
        record_secret,
        algorithm=ALGORITHM,
    )
    response = await client.post(
        f"/account/password_reset_confirmation?token={token}&user_id=68c302ef6bf7a039b7e9b385",
        json={"new_password": "NewPassword123!"},
    )
    assert response.status_code == 406
    assert response.json()["code"] == 406
    assert response.json()["error"] == "Invalid token type"
    assert "refresh_token" not in response.headers.get("set-cookie", "")
    assert response.headers["Cache-Control"] == "no-store"
    assert response.headers["Pragma"] == "no-cache"
    assert response.headers["x-content-type-options"] == "nosniff"
    assert response.headers["x-frame-options"] == "DENY"
    assert response.headers["referrer-policy"] == "strict-origin-when-cross-origin"
    assert response.headers["cross-origin-opener-policy"] == "same-origin-allow-popups"
    assert response.headers["strict-transport-security"] == "max-age=31536000; includeSubDomains"
    assert "permissions-policy" in response.headers
    # Lock the twelve most sensitive directives as disabled,
    # mirroring the wrong-user-token lock, using substring checks so
    # later additions to the list do not break this test.
    permissions_policy = response.headers["permissions-policy"]
    assert "camera=()" in permissions_policy
    assert "microphone=()" in permissions_policy
    assert "geolocation=()" in permissions_policy
    assert "payment=()" in permissions_policy
    assert "clipboard-read=()" in permissions_policy
    assert "display-capture=()" in permissions_policy
    assert "fullscreen=()" in permissions_policy
    assert "accelerometer=()" in permissions_policy
    assert "gyroscope=()" in permissions_policy
    assert "magnetometer=()" in permissions_policy
    assert "xr-spatial-tracking=()" in permissions_policy
    assert "idle-detection=()" in permissions_policy


