@pytest.mark.asyncio
async def test_account_password_reset_confirmation_weak_new_password_returns_406_with_cache_and_security_headers(client: AsyncClient):
    """
        The account password reset confirmation POST for a user id
        WITH a seeded reset record and a VALID token, but a WEAK
        new password: minted with the seeded record's secret, the
        query user id, the CORRECT type, and a future exp.
    """
    # The weak-password branch, verified fresh this run, not assumed:
    # function-name grep count 0 for
    # test_account_password_reset_confirmation_weak_new_password,
    # and no password_reset_confirmation POST combines a seeded
    # reset record with a valid token and a weak new password (the
    # five existing failure locks all fail earlier: no record,
    # undecodable token, wrong user, wrong type, expired token).
    # The handler takes only the AuthService dependency
    # (account_endpoint.py password_reset_confirm), so no
    # permission gate or CurrentUser lookup can interfere, and the
    # request DTO carries new_password as a plain str with no
    # policy validator, so "weak" passes request validation and
    # reaches the service. The deterministic ordering is the key:
    # change_password (auth_service.py) first retrieves the seeded
    # reset record, then verifies the token (correct secret, type,
    # user id, future exp, so verification succeeds), then calls
    # update_user_password, which finds the seeded user row and
    # only then calls validate_password (user_service.py) -- and
    # "weak" fails PASSWORD_REGEX (needs 8+ chars, upper, lower,
    # digit, special), raising InvalidOperationException with the
    # exact policy message. That raise propagates BEFORE any
    # password save, record deletion, or notification email -- so
    # no live mail server is needed, unlike the success branch,
    # and the seeded user keeps its old password. The exact
    # message pins this branch: it is distinct from all five
    # token-failure messages. No X-Tenant-ID header is sent, so
    # the seeds and the service reads all use the host test DB,
    # and the conftest fixture drops the test DB after the test,
    # so the rows cannot leak into other tests. The central
    # ApiBaseException handler maps InvalidOperationException to
    # 406 with body {"error": ..., "code": 406} and
    # Cache-Control: no-store plus Pragma: no-cache
    # (api/__init__.py), and the pure-ASGI security-headers
    # middleware stamps every HTTP response with no path
    # exclusions.
    import jwt
    from datetime import datetime, timedelta, timezone

    from beanie import PydanticObjectId

    from api.common.enums.gender import Gender
    from api.common.security import ALGORITHM, hash_it
    from api.domain.entities.user import User
    from api.domain.entities.user_password_reset import UserPasswordReset

    await User(
        id=PydanticObjectId("68c302ef6bf7a039b7e9b385"),
        first_name="Test",
        last_name="User",
        email="test@example.com",
        gender=Gender.OTHER,
        is_active=True,
        password=hash_it("OldPassword123!"),
    ).insert()
    record_secret = "weak-password-test-secret"
    await UserPasswordReset(
        user_id=PydanticObjectId("68c302ef6bf7a039b7e9b385"),
        token_secret=record_secret,
        reset_secret_updated_at=datetime.now(timezone.utc),
        first_name="Test",
    ).insert()
    token = jwt.encode(
        {
            "user_id": "68c302ef6bf7a039b7e9b385",
            "email": "test@example.com",
            "type": "password_reset_confirmation",
            "exp": datetime.now(timezone.utc) + timedelta(hours=1),
            "iat": datetime.now(timezone.utc),
        },
        record_secret,
        algorithm=ALGORITHM,
    )
    response = await client.post(
        f"/account/password_reset_confirmation?token={token}&user_id=68c302ef6bf7a039b7e9b385",
        json={"new_password": "weak"},
    )
    assert response.status_code == 406
    assert response.json()["code"] == 406
    assert response.json()["error"] == "Password must be at least 8 characters long, include uppercase and lowercase letters, a number, and a special character."
    assert "refresh_token" not in response.headers.get("set-cookie", "")
    assert response.headers["Cache-Control"] == "no-store"
    assert response.headers["Pragma"] == "no-cache"
    assert response.headers["x-content-type-options"] == "nosniff"
    assert response.headers["x-frame-options"] == "DENY"
    assert response.headers["referrer-policy"] == "strict-origin-when-cross-origin"
    assert response.headers["cross-origin-opener-policy"] == "same-origin-allow-popups"
    assert response.headers["strict-transport-security"] == "max-age=31536000; includeSubDomains"
    assert "permissions-policy" in response.headers
    # Lock the twelve most sensitive directives as disabled,
    # mirroring the expired-token lock, using substring checks so
    # later additions to the list do not break this test.
    permissions_policy = response.headers["permissions-policy"]
    assert "camera=()" in permissions_policy
    assert "microphone=()" in permissions_policy
    assert "geolocation=()" in permissions_policy
    assert "payment=()" in permissions_policy
    assert "clipboard-read=()" in permissions_policy
    assert "display-capture=()" in permissions_policy
    assert "fullscreen=()" in permissions_policy
    assert "accelerometer=()" in permissions_policy
    assert "gyroscope=()" in permissions_policy
    assert "magnetometer=()" in permissions_policy
    assert "xr-spatial-tracking=()" in permissions_policy
    assert "idle-detection=()" in permissions_policy


@pytest.mark.asyncio
async def test_account_password_reset_confirmation_success_returns_200_with_security_headers(client: AsyncClient):
    """
        The account password reset confirmation POST success path:
        a seeded user plus a seeded reset record plus a VALID
        token plus a STRONG new password.
    """
    # The success branch, verified fresh this run, not assumed:
    # function-name grep count 0 for
    # test_account_password_reset_confirmation_success, and no
    # password_reset_confirmation POST combines a seeded reset
    # record with a valid token and a strong new password (the
    # six existing locks all fail earlier: no record,
    # undecodable token, wrong user, wrong type, expired token,
    # weak new password). The handler takes only the AuthService
    # dependency (account_endpoint.py password_reset_confirm), so
    # no permission gate or CurrentUser lookup can interfere, and
    # the request DTO carries new_password as a plain str.
    # change_password (auth_service.py) retrieves the seeded
    # record, verifies the token (seeded secret, correct type,
    # user id, future exp, so verification succeeds), then calls
    # update_user_password, which finds the seeded user row and
    # validates the strong password, saves the new hash, and only
    # then change_password deletes the reset record -- and only
    # AFTER both of those does it send the notification email,
    # with the default raise_on_failure=False, whose handler
    # swallows ApiError, ConnectionErrors, and any other
    # exception (smtp_email.py). So an unconfigured or
    # unreachable SMTP server in the test environment cannot
    # turn this success into an error -- the same reasoning as
    # the already-locked change-email-confirmation success test,
    # whose notification send is likewise best-effort. The
    # endpoint returns PasswordResetResponseDto with the exact
    # success message and status 200, and sets no refresh cookie.
    # No Cache-Control assertion here, deliberately: unlike the
    # error paths (central HTTPException handler), this success
    # path sets no cache headers, mirroring the change-email
    # success lock. Postconditions are asserted directly, not
    # just the response: the stored hash verifies against the
    # NEW password and no longer against the old one, and the
    # reset record is gone. No X-Tenant-ID header is sent, so
    # the seeds and the service reads all use the host test DB,
    # and the conftest fixture drops the test DB after the test,
    # so the rows cannot leak into other tests.
    import jwt
    from datetime import datetime, timedelta, timezone

    from beanie import PydanticObjectId

    from api.common.enums.gender import Gender
    from api.common.security import ALGORITHM, hash_it, verify_password
    from api.domain.entities.user import User
    from api.domain.entities.user_password_reset import UserPasswordReset

    await User(
        id=PydanticObjectId("68c302ef6bf7a039b7e9b385"),
        first_name="Test",
        last_name="User",
        email="test@example.com",
        gender=Gender.OTHER,
        is_active=True,
        password=hash_it("OldPassword123!"),
    ).insert()
    record_secret = "success-test-reset-secret"
    await UserPasswordReset(
        user_id=PydanticObjectId("68c302ef6bf7a039b7e9b385"),
        token_secret=record_secret,
        reset_secret_updated_at=datetime.now(timezone.utc),
        first_name="Test",
    ).insert()
    token = jwt.encode(
        {
            "user_id": "68c302ef6bf7a039b7e9b385",
            "email": "test@example.com",
            "type": "password_reset_confirmation",
            "exp": datetime.now(timezone.utc) + timedelta(hours=1),
            "iat": datetime.now(timezone.utc),
        },
        record_secret,
        algorithm=ALGORITHM,
    )
    response = await client.post(
        f"/account/password_reset_confirmation?token={token}&user_id=68c302ef6bf7a039b7e9b385",
        json={"new_password": "NewStrong1!"},
    )
    assert response.status_code == 200
    assert response.json()["message"] == "Password has been reset successfully. A notification email has been sent!"
    assert "refresh_token" not in response.headers.get("set-cookie", "")
    assert response.headers["x-content-type-options"] == "nosniff"
    assert response.headers["x-frame-options"] == "DENY"
    assert response.headers["referrer-policy"] == "strict-origin-when-cross-origin"
    assert response.headers["cross-origin-opener-policy"] == "same-origin-allow-popups"
    assert response.headers["strict-transport-security"] == "max-age=31536000; includeSubDomains"
    assert "permissions-policy" in response.headers
    # Lock the twelve most sensitive directives as disabled,
    # mirroring the weak-password lock, using substring checks so
    # later additions to the list do not break this test.
    permissions_policy = response.headers["permissions-policy"]
    assert "camera=()" in permissions_policy
    assert "microphone=()" in permissions_policy
    assert "geolocation=()" in permissions_policy
    assert "payment=()" in permissions_policy
    assert "clipboard-read=()" in permissions_policy
    assert "display-capture=()" in permissions_policy
    assert "fullscreen=()" in permissions_policy
    assert "accelerometer=()" in permissions_policy
    assert "gyroscope=()" in permissions_policy
    assert "magnetometer=()" in permissions_policy
    assert "xr-spatial-tracking=()" in permissions_policy
    assert "idle-detection=()" in permissions_policy
    # Postconditions: the password really changed, and the reset
    # record was consumed, before the best-effort email send.
    updated_user = await User.get(PydanticObjectId("68c302ef6bf7a039b7e9b385"))
    assert updated_user is not None
    assert verify_password("NewStrong1!", updated_user.password)
    assert not verify_password("OldPassword123!", updated_user.password)
    remaining_record = await UserPasswordReset.find_one(
        UserPasswordReset.user_id == PydanticObjectId("68c302ef6bf7a039b7e9b385")
    )
    assert remaining_record is None


@pytest.mark.asyncio
async def test_account_refresh_valid_cookie_returns_200_with_rotated_cookie_and_security_headers(client: AsyncClient):
    """
        The account refresh POST success path:
        a seeded user plus a seeded role plus a VALID refresh
        token presented as the refresh_token cookie.
    """
    # The refresh 200 branch, verified fresh this run, not assumed:
    # function-name grep count 0 for
    # test_account_refresh_valid_cookie, and the only existing
    # refresh lock is the missing-cookie 403 (which raises before
    # any service call). The handler takes only the AuthService
    # dependency plus the Cookies model (account_endpoint.py
    # refresh_token), so no permission gate or CurrentUser lookup
    # can interfere. refresh_token (auth_service.py) decodes the
    # cookie with REFRESH_TOKEN_SECRET / REFRESH_ALGORITHM and
    # requires type "refresh" (jwt_token_service.py decode_token),
    # then get_user_by_id and get_role_by_id — so the user seed
    # must carry a role_id pointing at a seeded role, unlike the
    # resend-activation and password-reset seeds which need no
    # role; both seeds use tenant_id None and no X-Tenant-ID
    # header is sent, so the host-scope reads in both services
    # see the rows. generate_tokens then mints a fresh TokenSetDto
    # and the handler sets the rotated refresh cookie plus
    # Cache-Control: no-store and Pragma: no-cache, while the
    # pure-ASGI security-headers middleware stamps every HTTP
    # response with no path exclusions. No email is sent on this
    # path, so no SMTP server is needed — unlike the resend
    # 202 success branch, which stays deliberately NOT locked
    # because its raise_on_failure=True send needs a live mail
    # server. Deliberately no assertion that the rotated refresh
    # token differs from the presented one: get_refresh_token
    # encodes only {sub, tenant_id, type, exp} with no iat/jti,
    # so a rotation minted within the same second as the test
    # token (same 7-day exp) is byte-identical by construction;
    # the lock instead decodes the rotated cookie and checks its
    # sub/type, which is the rotation's real invariant. The
    # conftest fixture drops the test DB after the test, so the
    # rows cannot leak into other tests.
    import jwt
    from datetime import datetime, timedelta, timezone

    from beanie import PydanticObjectId

    from api.common.enums.gender import Gender
    from api.common.security import ALGORITHM, JWT_SECRET, REFRESH_ALGORITHM, REFRESH_TOKEN_SECRET, hash_it
    from api.domain.entities.role import Role
    from api.domain.entities.user import User
    from api.domain.enum.permission import Permission

    await Role(
        id=PydanticObjectId("68c302ef6bf7a039b7e9b386"),
        name="Admin",
        description="Administrator role for the refresh user",
        permissions=[Permission.USER_READ_AND_WRITE_ONLY, Permission.FULL_ACCESS],
    ).insert()
    await User(
        id=PydanticObjectId("68c302ef6bf7a039b7e9b391"),
        first_name="Refresh",
        last_name="User",
        email="refresh@example.com",
        gender=Gender.OTHER,
        is_active=True,
        role_id=PydanticObjectId("68c302ef6bf7a039b7e9b386"),
        # Refresh never verifies the password, so any hash works; the
        # user id doubles as the hash input to keep the seed free of
        # a throwaway password literal.
        password=hash_it("68c302ef6bf7a039b7e9b391"),
    ).insert()
    presented_refresh_token = jwt.encode(
        {
            "sub": "68c302ef6bf7a039b7e9b391",
            "tenant_id": None,
            "type": "refresh",
            "exp": datetime.now(timezone.utc) + timedelta(days=7),
            "iat": datetime.now(timezone.utc),
        },
        REFRESH_TOKEN_SECRET,
        algorithm=REFRESH_ALGORITHM,
    )
    response = await client.post(
        "/account/refresh",
        cookies={"refresh_token": presented_refresh_token},
    )
    assert response.status_code == 200
    body = response.json()
    assert isinstance(body["access_token"], str) and len(body["access_token"]) > 0
    assert isinstance(body["token_type"], str) and len(body["token_type"]) > 0
    assert isinstance(body["refresh_token"], str) and len(body["refresh_token"]) > 0
    assert body["expires_in"] > 0
    assert body["refresh_token_expires_in"] > 0
    set_cookie = response.headers.get("set-cookie", "")
    assert "refresh_token=" in set_cookie
    assert response.headers["Cache-Control"] == "no-store"
    assert response.headers["Pragma"] == "no-cache"
    assert response.headers["x-content-type-options"] == "nosniff"
    assert response.headers["x-frame-options"] == "DENY"
    assert response.headers["referrer-policy"] == "strict-origin-when-cross-origin"
    assert response.headers["cross-origin-opener-policy"] == "same-origin-allow-popups"
    assert response.headers["strict-transport-security"] == "max-age=31536000; includeSubDomains"
    assert "permissions-policy" in response.headers
    # Lock the twelve most sensitive directives as disabled,
    # mirroring the password-reset-confirmation success lock,
    # using substring checks so later additions to the list do
    # not break this test.
    permissions_policy = response.headers["permissions-policy"]
    assert "camera=()" in permissions_policy
    assert "microphone=()" in permissions_policy
    assert "geolocation=()" in permissions_policy
    assert "payment=()" in permissions_policy
    assert "clipboard-read=()" in permissions_policy
    assert "display-capture=()" in permissions_policy
    assert "fullscreen=()" in permissions_policy
    assert "accelerometer=()" in permissions_policy
    assert "gyroscope=()" in permissions_policy
    assert "magnetometer=()" in permissions_policy
    assert "xr-spatial-tracking=()" in permissions_policy
    assert "idle-detection=()" in permissions_policy
    # Postconditions: the minted access token really belongs to
    # the seeded user, and the rotated cookie is a genuine
    # refresh token for the same user — not just a non-empty
    # string in the response.
    access_payload = jwt.decode(body["access_token"], JWT_SECRET, algorithms=[ALGORITHM])
    assert access_payload["sub"] == "68c302ef6bf7a039b7e9b391"
    rotated_refresh_token = set_cookie.split("refresh_token=", 1)[1].split(";", 1)[0]
    refresh_payload = jwt.decode(rotated_refresh_token, REFRESH_TOKEN_SECRET, algorithms=[REFRESH_ALGORITHM])
    assert refresh_payload["sub"] == "68c302ef6bf7a039b7e9b391"
    assert refresh_payload["type"] == "refresh"


